package com.homestay.model;

import java.io.Serializable;
import java.math.BigDecimal;
import java.sql.Timestamp;

/**
 * Recommendation Model - Represents personalized room recommendations
 * generated by the AI Recommender engine for customers.
 */
public class Recommendation implements Serializable {
    private static final long serialVersionUID = 1L;

    private long recommendationId;
    private Integer userId;
    private Integer roomId;
    private Integer propertyId;
    private Integer roomTypeId;
    private Long tourId;
    private String recommendationType; // 'CONTENT_BASED', 'BUDGET_MATCH', 'BEHAVIOR_BASED', 'POPULAR'
    private double score;              // 0.0000 - 1.0000 (e.g. 0.95 = 95%)
    private String reason;             // Friendly explanation displayed to user
    private boolean isDisplayed = true;
    private Timestamp createdAt;

    // Associated room details for rendering on catalog & discovery UI
    private Room room;

    public Recommendation() {
    }

    public Recommendation(Integer userId, Integer roomId, String recommendationType, double score, String reason) {
        this.userId = userId;
        this.roomId = roomId;
        this.recommendationType = recommendationType;
        this.score = score;
        this.reason = reason;
        this.isDisplayed = true;
    }

    public long getRecommendationId() {
        return recommendationId;
    }

    public void setRecommendationId(long recommendationId) {
        this.recommendationId = recommendationId;
    }

    public Integer getUserId() {
        return userId;
    }

    public void setUserId(Integer userId) {
        this.userId = userId;
    }

    public Integer getRoomId() {
        return roomId;
    }

    public void setRoomId(Integer roomId) {
        this.roomId = roomId;
    }

    public Integer getPropertyId() {
        return propertyId;
    }

    public void setPropertyId(Integer propertyId) {
        this.propertyId = propertyId;
    }

    public Integer getRoomTypeId() {
        return roomTypeId;
    }

    public void setRoomTypeId(Integer roomTypeId) {
        this.roomTypeId = roomTypeId;
    }

    public Long getTourId() {
        return tourId;
    }

    public void setTourId(Long tourId) {
        this.tourId = tourId;
    }

    public String getRecommendationType() {
        return recommendationType;
    }

    public void setRecommendationType(String recommendationType) {
        this.recommendationType = recommendationType;
    }

    public double getScore() {
        return score;
    }

    public void setScore(double score) {
        this.score = score;
    }

    public String getReason() {
        return reason;
    }

    public void setReason(String reason) {
        this.reason = reason;
    }

    public boolean isDisplayed() {
        return isDisplayed;
    }

    public void setDisplayed(boolean displayed) {
        isDisplayed = displayed;
    }

    public Timestamp getCreatedAt() {
        return createdAt;
    }

    public void setCreatedAt(Timestamp createdAt) {
        this.createdAt = createdAt;
    }

    public Room getRoom() {
        return room;
    }

    public void setRoom(Room room) {
        this.room = room;
    }

    /**
     * Percentage match for display (e.g., 96%)
     */
    public int getMatchPercentage() {
        if (score <= 0.0) return 90;
        int pct = (int) Math.round(score * 100);
        if (pct > 100) return 100;
        if (pct < 70) return 85;
        return pct;
    }

    /**
     * User-facing label in Vietnamese based on recommendation type.
     */
    public String getTypeLabel() {
        if ("BUDGET_MATCH".equalsIgnoreCase(recommendationType)) {
            return "Phù hợp ngân sách";
        } else if ("CONTENT_BASED".equalsIgnoreCase(recommendationType)) {
            return "Dựa trên sở thích";
        } else if ("BEHAVIOR_BASED".equalsIgnoreCase(recommendationType)) {
            return "Tương tự đã xem";
        } else {
            return "Được yêu thích nhất";
        }
    }

    /**
     * Badge CSS class for badge styling.
     */
    public String getTypeBadgeClass() {
        if ("BUDGET_MATCH".equalsIgnoreCase(recommendationType)) {
            return "badge-ai-budget";
        } else if ("CONTENT_BASED".equalsIgnoreCase(recommendationType)) {
            return "badge-ai-preference";
        } else if ("BEHAVIOR_BASED".equalsIgnoreCase(recommendationType)) {
            return "badge-ai-behavior";
        } else {
            return "badge-ai-popular";
        }
    }

    /**
     * FontAwesome icon name based on recommendation type.
     */
    public String getTypeIcon() {
        if ("BUDGET_MATCH".equalsIgnoreCase(recommendationType)) {
            return "fa-money";
        } else if ("CONTENT_BASED".equalsIgnoreCase(recommendationType)) {
            return "fa-compass";
        } else if ("BEHAVIOR_BASED".equalsIgnoreCase(recommendationType)) {
            return "fa-heart";
        } else {
            return "fa-fire";
        }
    }
}

